using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Rod of Lordly Might (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class RodOfLordlyMight2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("rod-of-lordly-might", null, 0, MagicItemType.Rod, ItemRarity.Legendary, true, ContentSource.Srd51,
			Magic(Effect(MagicEffectKind.AttackAndDamage, 3)),
			("Verga della potenza divina", "Verga, leggendaria (richiede sintonia)",
			"Questa verga ha una testa flangiata e funziona come una mazza magica che conferisce un bonus di +3 ai tiri per colpire e ai tiri per i danni effettuati con essa. Possiede una serie di proprietà associate a sei pulsanti diversi disposti in fila lungo l'asta. Possiede anche le tre proprietà descritte di seguito.\n\n***Sei pulsanti.*** Come azione bonus, il personaggio può premere uno dei sei pulsanti della verga. L'effetto di un pulsante dura finché il personaggio non ne preme un altro o finché non lo preme di nuovo, riportando la verga alla sua forma originaria.\n\nSe il personaggio preme il **pulsante 1,** la verga diventa una *lingua di fiamme* e una lama fiammeggiante spunta dall'estremità opposta alla testa flangiata.\n\nSe il personaggio preme il **pulsante 2,** la testa flangiata della verga si ritrae e due lame a forma di mezzaluna spuntano da quell'estremità, trasformando la verga in un'ascia da battaglia magica che conferisce un bonus di +3 ai tiri per colpire e ai tiri per i danni effettuati con essa.\n\nSe il personaggio preme il **pulsante 3,** la testa flangiata della verga si ritrae, una punta di lancia spunta da quell'estremità e l'impugnatura si allunga fino a diventare un'asta lunga 1,8 metri, trasformando la verga in una lancia magica che conferisce un bonus di +3 ai tiri per colpire e ai tiri per i danni effettuati con essa.\n\nSe il personaggio preme il **pulsante 4,** la verga si trasforma in una pertica di una lunghezza a sua scelta, fino a un massimo di 15 metri. Sulle superfici dure come il granito, la pertica viene fissata grazie a uno spuntone sul fondo e a tre uncini sulla cima. Dai lati spuntano delle sbarre lunghe 7,5 cm a intervalli di 30 cm che formano una scala a pioli. La pertica può reggere un peso massimo di 2.000 kg. Un peso superiore o la mancanza di un ancoraggio sicuro fa tornare la verga alla sua forma originaria.\n\nSe il personaggio preme il **pulsante 5,** la verga si trasforma in un ariete portatile e conferisce un bonus di +10 alle prove di Forza effettuate per abbattere porte, barricate e altri ostacoli.\n\nSe il personaggio preme il **pulsante 6,** la verga rimane nella sua forma originaria o la riassume e indica il nord magnetico. (Se questa funzione viene usata in un luogo dove non esiste un nord magnetico, non accade nulla.) La verga fornisce inoltre al personaggio un'indicazione approssimativa della profondità o dell'altitudine a cui si trova rispetto al terreno.\n\n***Paralisi.*** Quando il personaggio colpisce una creatura con un attacco in mischia usando la verga, può obbligare il bersaglio a effettuare un tiro salvezza su Forza con CD 17. In caso di fallimento, il bersaglio rimane paralizzato per 1 minuto. Il bersaglio può ripetere il tiro salvezza alla fine di ogni suo turno e, se lo supera, l'effetto svanisce. Questa proprietà non può essere riutilizzata fino all'alba successiva.\n\n***Risucchio vitale.*** Quando il personaggio colpisce una creatura con un attacco in mischia usando la verga, può obbligare il bersaglio a effettuare un tiro salvezza su Costituzione con CD 17. In caso di fallimento, il bersaglio subisce 4d6 danni necrotici extra e il personaggio recupera un numero di punti ferita pari alla metà di quei danni. Questa proprietà non può essere riutilizzata fino all'alba successiva.\n\n***Terrificante.*** Mentre il personaggio impugna la verga, può usare un'azione per costringere tutte le creature situate entro 9 metri da lui che è in grado di vedere a effettuare un tiro salvezza su Saggezza con CD 17. In caso di fallimento, il bersaglio rimane spaventato per 1 minuto. Il bersaglio spaventato può ripetere il tiro salvezza alla fine di ogni suo turno e, se lo supera, l'effetto svanisce. Questa proprietà non può essere riutilizzata fino all'alba successiva."),
			("Rod of Lordly Might", "Rod, legendary (requires attunement)",
			"This rod has a flanged head, and it functions as a magic mace that grants a +3 bonus to attack and damage rolls made with it. The rod has properties associated with six different buttons that are set in a row along the haft. It has three other properties as well, detailed below.\n\n***Six Buttons.*** You can press one of the rod's six buttons as a bonus action. A button's effect lasts until you push a different button or until you push the same button again, which causes the rod to revert to its normal form.\n\nIf you press **button 1**, the rod becomes a flame tongue, as a fiery blade sprouts from the end opposite the rod's flanged head.\n\nIf you press **button 2**, the rod's flanged head folds down and two crescent-shaped blades spring out, transforming the rod into a magic battleaxe that grants a +3 bonus to attack and damage rolls made with it.\n\nIf you press **button 3**, the rod's flanged head folds down, a spear point springs from the rod's tip, and the rod's handle lengthens into a 6-foot haft, transforming the rod into a magic spear that grants a +3 bonus to attack and damage rolls made with it.\n\nIf you press **button 4**, the rod transforms into a climbing pole up to 50 feet long, as you specify. In surfaces as hard as granite, a spike at the bottom and three hooks at the top anchor the pole. Horizontal bars 3 inches long fold out from the sides, 1 foot apart, forming a ladder. The pole can bear up to 4,000 pounds. More weight or lack of solid anchoring causes the rod to revert to its normal form.\n\nIf you press **button 5**, the rod transforms into a handheld battering ram and grants its user a +10 bonus to Strength checks made to break through doors, barricades, and other barriers.\n\nIf you press **button 6**, the rod assumes or remains in its normal form and indicates magnetic north. (Nothing happens if this function of the rod is used in a location that has no magnetic north.) The rod also gives you knowledge of your approximate depth beneath the ground or your height above it.\n\n***Drain Life.*** When you hit a creature with a melee attack using the rod, you can force the target to make a DC 17 Constitution saving throw. On a failure, the target takes an extra 4d6 necrotic damage, and you regain a number of hit points equal to half that necrotic damage. This property can't be used again until the next dawn.\n\n***Paralyze.*** When you hit a creature with a melee attack using the rod, you can force the target to make a DC 17 Strength saving throw. On a failure, the target is paralyzed for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on a success. This property can't be used again until the next dawn.\n\n***Terrify.*** While holding the rod, you can use an action to force each creature you can see within 30 feet of you to make a DC 17 Wisdom saving throw. On a failure, a target is frightened of you for 1 minute. A frightened target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. This property can't be used again until the next dawn.", null));
	}
}
